## Why This Is Asked
Tests practical error handling, DLQ patterns, offset management, and testability in a beginner KCNA context.

## Key Concepts
- JSON deserialization and field validation
- Dead-letter queue (DLQ) strategy
- Per-message offset handling and commit semantics
- Idempotent sinks and at-least-once delivery guarantees

## Code Example
```javascript
// Consumer API surface
interface ConsumerContext {
  message: {
    key: Buffer;
    value: Buffer;
    partition: number;
    offset: bigint;
  };
  emit(topic: string, key: Buffer, value: Buffer): Promise<void>;
  commit(): Promise<void>;
}

type MessageHandler = (ctx: ConsumerContext) => Promise<void>;

// Implementation
async function onMessage(ctx: ConsumerContext): Promise<void> {
  try {
    const m = JSON.parse(ctx.message.value.toString());

    if (!m.orderId || !m.customerId || m.total == null) {
      throw new Error('missing required fields: orderId, customerId, total');
    }

    const enriched = {
      ...m,
      processedAt: new Date().toISOString(),
      sourcePartition: ctx.message.partition,
      sourceOffset: ctx.message.offset.toString()
    };

    await ctx.emit('orders_enriched', ctx.message.key, JSON.stringify(enriched));
    await ctx.commit();
  } catch (err) {
    const dlqRecord = {
      originalKey: ctx.message.key?.toString() ?? null,
      partition: ctx.message.partition,
      offset: ctx.message.offset.toString(),
      error: err instanceof Error ? err.message : String(err),
      timestamp: new Date().toISOString()
    };

    await ctx.emit('dead_letter', ctx.message.key, JSON.stringify(dlqRecord));
    await ctx.commit();
  }
}
```

